'

node -e '
// Independent source of truth: spec says subtotal * 0.9, rounded to nearest cent.
const rows = [["150.00","135.00"],["100.01","90.01"],["100.00","100.00"],["99.99","99.99"],["0.00","0.00"],["250.00","225.00"],["109.99","98.99"]];
for (const [sub, exp] of rows) {
  const t = parseFloat(sub);
  const raw = t > 100 ? t * (1 - 10/100) : t;
  const cents = Math.round(raw * 100) / 100;
  const ok = cents.toFixed(2) === exp ? "OK " : "MISMATCH";
  console.log(ok, sub.padStart(7), "raw:", String(raw).padEnd(22), "-> got", cents.toFixed(2), "| spec says", exp);
}
'

