// Money assertions work in integer cents so binary float representation can
// neither mask a wrong value nor fail a right one.
function centsOf(value) {
  return Math.round(value * 100);
}

// Guards against a total that carries sub-cent precision (e.g. 90.009)
// rounding to the expected cent in the assertion itself. A total that has not
// been rounded to money must not be able to pass.
function assertCentExact(value) {
  assert.ok(
    Math.abs(value * 100 - centsOf(value)) < 1e-9,
    `expected a total rounded to the nearest cent, got ${value}`,
  );
}

Given("an order with a subtotal of ${float}", function (subtotal) {
  this.subtotal = subtotal;
});

When("the order total is calculated", function () {
  this.total = orderTotal(this.subtotal);
});

Then("the order total should be ${float}", function (expected) {
  assertCentExact(this.total);
  assert.equal(
    centsOf(this.total),
    centsOf(expected),
    `expected a total of $${expected.toFixed(2)}, got $${this.total}`,
  );
});

